+++ b/src/orchestration/chatOrchestrator.ts
@@ -147,9 +147,7 @@ export function createChatOrchestrator(

         if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
       } catch (error) {
-        if (hooks?.onError && error instanceof Error) {
-          await hooks.onError(session, error);
-        }
+        if (hooks?.onError) await hooks.onError(session, asError(error));
         throw error;
       } finally {
         // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
@@ -164,6 +162,22 @@ export function createChatOrchestrator(
   };
 }

+// A thrown non-Error reaches onError wrapped, the original kept as cause; the caller still sees the raw value.
+function asError(thrown: unknown): Error {
+  if (thrown instanceof Error) return thrown;
+  return new Error(describeThrown(thrown), {cause: thrown});
+}
+
+// Must never throw: JSON.stringify does on a circular object or a BigInt, and that would replace the caller's rejection.
+function describeThrown(thrown: unknown): string {
+  if (typeof thrown === 'string') return thrown;
+  try {
+    return JSON.stringify(thrown) ?? String(thrown);
+  } catch {
+    return 'non-Error value thrown';
+  }
+}
+
 // A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
 function normalizeToolRounds(value: number | undefined): number {
   if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;

