index 0124d8c..54704c7 100644
--- a/src/orchestration/chatOrchestrator.test.ts
+++ b/src/orchestration/chatOrchestrator.test.ts
@@ -36,7 +36,7 @@ function createMockProvider(response: string, usage?: UsageMetadata): AIProvider
   };
 }

-function createErrorProvider(error: Error): AIProvider {
+function createErrorProvider(error: unknown): AIProvider {
   return {
     // eslint-disable-next-line require-yield
     async *sendMessage(): AsyncGenerator<MessageChunk> {
@@ -50,6 +50,22 @@ function createErrorProvider(error: Error): AIProvider {

 const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

+// What onError received for a turn that rejects with `reason`, and what the caller was rethrown.
+const rejectionSeenBy = async (reason: unknown): Promise<{rethrown: unknown; received: Error | undefined}> => {
+  let received: Error | undefined;
+  const hooks: OrchestratorHooks = {
+    onError: async (_session, error) => {
+      received = error;
+    },
+  };
+  const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
+  const rethrown = await orchestrator.processMessage(createSession('hello')).then(
+    () => 'resolved without throwing',
+    (thrown: unknown) => thrown
+  );
+  return {rethrown, received};
+};
+
 type RecordedHook =
   | 'beforeSession'
   | 'beforeUserInput'
@@ -307,6 +323,30 @@ describe('ChatOrchestrator hooks', () => {
       });
       await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
     });
+
+    it('wraps an undefined rejection in an Error whose cause is undefined, and rethrows undefined', async () => {
+      const {rethrown, received} = await rejectionSeenBy(undefined);
+
+      expect({
+        rethrown,
+        isError: received instanceof Error,
+        hasCause: received !== undefined && 'cause' in received,
+        cause: received?.cause,
+      }).toEqual({rethrown: undefined, isError: true, hasCause: true, cause: undefined});
+    });
+
+    it('wraps a circular-object rejection without throwing, and rethrows the original object', async () => {
+      const circular: Record<string, unknown> = {code: 503};
+      circular.self = circular;
+      const {rethrown, received} = await rejectionSeenBy(circular);
+
+      expect({
+        rethrownIsOriginal: rethrown === circular,
+        isError: received instanceof Error,
+        hasMessage: (received?.message ?? '').length > 0,
+        causeIsOriginal: received?.cause === circular,
+      }).toEqual({rethrownIsOriginal: true, isError: true, hasMessage: true, causeIsOriginal: true});
+    });
   });

   describe('full lifecycle order', () => {
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content, timestamp: '2026-01-01T00:00:00.000Z'}],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const turnOutcome = async (reason: unknown) => {
  const callOrder: string[] = [];
  let seenError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      callOrder.push('onError');
      seenError = error;
    },
    afterSession: async () => {
      callOrder.push('afterSession');
    },
  };

  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});
  const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
    value => ({rejected: false, reason: value as unknown}),
    (thrown: unknown) => ({rejected: true, reason: thrown})
  );

  return {
    outcome,
    callOrder,
    isError: seenError instanceof Error,
    message: seenError?.message,
  };
};

describe('ChatOrchestrator onError on non-Error rejections', () => {
  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    const result = await turnOutcome('string boom');

    expect(result).toEqual({
      outcome: {rejected: true, reason: 'string boom'},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      message: 'string boom',
    });
  });

  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    const reason = {code: 503, detail: 'upstream down'};

    const result = await turnOutcome(reason);

    expect({
      outcome: result.outcome,
      callOrder: result.callOrder,
      isError: result.isError,
      hasMessage: typeof result.message === 'string' && result.message.length > 0,
    }).toEqual({
      outcome: {rejected: true, reason},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      hasMessage: true,
    });
  });
});

